package com.datarewindingmotorac;

import android.app.*; import android.os.Bundle; import android.content.*; import android.database.Cursor; import android.database.sqlite.*;
import android.graphics.Color; import android.graphics.Typeface; import android.graphics.drawable.GradientDrawable; import android.view.*; import android.widget.*; import android.text.*; import android.content.res.ColorStateList;

public class MainActivity extends Activity {
 DB db; LinearLayout root,list; EditText search; Spinner filter; boolean favOnly=false;
 final String[] cats={"Umum","Data Motor","Lilitan / Winding","Pengukuran","Kerusakan","Perbaikan","Material"};
 int paper=Color.rgb(255,249,231),brown=Color.rgb(104,68,38),ink=Color.rgb(54,48,40),red=Color.rgb(151,48,39),gold=Color.rgb(183,132,43),muted=Color.rgb(120,105,83);
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 LinearLayout horizontal(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);build();}
 void build(){
  ScrollView page=new ScrollView(this);page.setFillViewport(true);page.setBackgroundColor(Color.rgb(226,216,194));root=vertical();root.setPadding(dp(14),dp(14),dp(14),dp(22));page.addView(root);
  LinearLayout cover=vertical();cover.setPadding(dp(20),dp(22),dp(20),dp(22));cover.setBackground(shape(Color.rgb(91,45,34),18));LinearLayout.LayoutParams cvp=new LinearLayout.LayoutParams(-1,-2);cvp.bottomMargin=dp(14);root.addView(cover,cvp);
  LinearLayout emblem=horizontal();TextView gear=txt("⚙",34,gold,true);gear.setGravity(Gravity.CENTER);emblem.addView(gear,new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout labels=vertical();labels.setPadding(dp(10),0,0,0);labels.addView(txt("BUKU CATATAN TEKNIK",11,Color.rgb(239,214,159),true));labels.addView(txt("REWINDING MOTOR AC",20,Color.WHITE,true));emblem.addView(labels);cover.addView(emblem);
  View line=new View(this);line.setBackgroundColor(gold);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(1));lp.setMargins(0,dp(14),0,dp(10));cover.addView(line,lp);cover.addView(txt("CATATAN • DATA • PENGUKURAN • PERBAIKAN",10,Color.rgb(245,224,185),true));
  LinearLayout quick=horizontal();quick.setPadding(0,dp(12),0,dp(8));root.addView(quick);tile(quick,"＋","Tulis Catatan",red,()->edit(null));tile(quick,"⌕","Cari Isi Buku",Color.rgb(74,105,79),()->{search.requestFocus();search.postDelayed(()->((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(search,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT),180);});
  LinearLayout quick2=horizontal();root.addView(quick2);tile(quick2,"▤","Daftar Bab",brown,()->new AlertDialog.Builder(this).setTitle("Daftar Bab").setItems(cats,(d,w)->filter.setSelection(w+1)).show());tile(quick2,"★","Halaman Favorit",gold,()->{favOnly=!favOnly;refresh();});
  TextView heading=txt("ISI BUKU CATATAN",13,brown,true);heading.setPadding(dp(4),dp(18),0,dp(8));root.addView(heading);
  search=new EditText(this);search.setSingleLine(true);search.setTextSize(14);search.setHint("Cari judul atau isi catatan...");search.setPadding(dp(14),dp(10),dp(14),dp(10));search.setTextColor(ink);search.setHintTextColor(muted);search.setBackground(shape(paper,10));root.addView(search,new LinearLayout.LayoutParams(-1,dp(46)));
  filter=new Spinner(this);filter.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Semua bab","Umum","Data Motor","Lilitan / Winding","Pengukuran","Kerusakan","Perbaikan","Material"}));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(42));fp.topMargin=dp(6);root.addView(filter,fp);
  list=vertical();root.addView(list);Button add=new Button(this);add.setText("＋  TAMBAH HALAMAN");add.setTextColor(Color.WHITE);add.setBackgroundTintList(ColorStateList.valueOf(red));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(50));ap.topMargin=dp(12);root.addView(add,ap);add.setOnClickListener(v->edit(null));
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh();}public void afterTextChanged(Editable e){}});
  filter.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){refresh();}});
  setContentView(page);refresh();
 }
 void tile(LinearLayout row,String symbol,String label,int color,Runnable action){LinearLayout box=vertical();box.setGravity(Gravity.CENTER);box.setPadding(dp(6),dp(9),dp(6),dp(9));box.setBackground(shape(color,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(78),1);p.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(box,p);box.addView(txt(symbol,23,Color.WHITE,true));box.addView(txt(label,11,Color.WHITE,true));box.setOnClickListener(v->action.run());}
 void refresh(){
  if(list==null||search==null||filter==null)return;list.removeAllViews();String q=search.getText().toString().trim().toLowerCase();String cat=filter.getSelectedItemPosition()==0?"":cats[filter.getSelectedItemPosition()-1];
  Cursor c=db.getReadableDatabase().rawQuery("SELECT id,title,body,category,favorite FROM notes ORDER BY favorite DESC,updated DESC",null);int count=0;
  while(c.moveToNext()){int id=c.getInt(0),fav=c.getInt(4);String t=c.getString(1),body=c.getString(2),category=c.getString(3);if(favOnly&&fav==0)continue;if(!cat.isEmpty()&&!cat.equals(category))continue;if(!q.isEmpty()&&!t.toLowerCase().contains(q)&&!body.toLowerCase().contains(q))continue;count++;
   LinearLayout card=horizontal();card.setBackground(shape(paper,7));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(dp(2),dp(5),dp(2),dp(5));list.addView(card,cp);View spine=new View(this);spine.setBackgroundColor(red);card.addView(spine,new LinearLayout.LayoutParams(dp(7),-1));
   LinearLayout pageBody=vertical();pageBody.setPadding(dp(13),dp(12),dp(13),dp(12));card.addView(pageBody,new LinearLayout.LayoutParams(0,-2,1));LinearLayout titleRow=horizontal();TextView title=txt(t,15,ink,true);titleRow.addView(title,new LinearLayout.LayoutParams(0,-2,1));titleRow.addView(txt(fav==1?"★":"☆",20,gold,true));pageBody.addView(titleRow);
   TextView meta=txt("BAB: "+category.toUpperCase(),10,red,true);meta.setPadding(0,dp(4),0,dp(5));pageBody.addView(meta);TextView desc=txt(body.isEmpty()?"Belum ada isi catatan.":body,13,muted,false);desc.setMaxLines(3);pageBody.addView(desc);TextView number=txt("✦  HALAMAN "+count,9,gold,true);number.setGravity(Gravity.RIGHT);number.setPadding(0,dp(7),0,0);pageBody.addView(number);
   card.setOnClickListener(v->edit(id));card.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("Hapus halaman?").setMessage(t).setNegativeButton("Batal",null).setPositiveButton("Hapus",(d,w)->{db.getWritableDatabase().delete("notes","id=?",new String[]{""+id});refresh();}).show();return true;});
  }
  c.close();if(count==0){LinearLayout empty=vertical();empty.setGravity(Gravity.CENTER);empty.setPadding(dp(10),dp(28),dp(10),dp(28));empty.setBackground(shape(paper,8));empty.addView(txt("▤",34,gold,true));empty.addView(txt("Halaman masih kosong",15,brown,true));empty.addView(txt("Tekan Tambah Halaman untuk menulis catatan pertama.",12,muted,false));list.addView(empty);}
 }
 void edit(Integer id){
  String ot="",ob="",oc="Umum";boolean of=false;if(id!=null){Cursor c=db.getReadableDatabase().rawQuery("SELECT title,body,category,favorite FROM notes WHERE id=?",new String[]{""+id});if(c.moveToFirst()){ot=c.getString(0);ob=c.getString(1);oc=c.getString(2);of=c.getInt(3)==1;}c.close();}
  LinearLayout form=vertical();form.setPadding(dp(18),dp(8),dp(18),0);form.setBackgroundColor(paper);TextView prompt=txt("HALAMAN CATATAN TEKNIK",11,red,true);prompt.setPadding(0,0,0,dp(5));form.addView(prompt);
  EditText title=new EditText(this);title.setSingleLine(true);title.setHint("Judul halaman / catatan");title.setText(ot);title.setTextColor(ink);title.setHintTextColor(muted);title.setBackgroundTintList(ColorStateList.valueOf(gold));form.addView(title);
  Spinner category=new Spinner(this);category.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,cats));for(int i=0;i<cats.length;i++)if(cats[i].equals(oc))category.setSelection(i);form.addView(category);
  EditText body=new EditText(this);body.setHint("Tuliskan data motor, ukuran kawat, jumlah lilitan, hasil ukur, dan catatan pekerjaan...");body.setText(ob);body.setTextColor(ink);body.setHintTextColor(muted);body.setMinLines(6);body.setGravity(Gravity.TOP);body.setPadding(dp(8),dp(8),dp(8),dp(8));body.setBackground(shape(Color.rgb(255,253,245),5));form.addView(body);
  CheckBox favorite=new CheckBox(this);favorite.setText("Simpan di halaman favorit");favorite.setTextColor(brown);favorite.setChecked(of);form.addView(favorite);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle(id==null?"Tulis Halaman Baru":"Edit Halaman").setView(form).setNegativeButton("Batal",null).setPositiveButton("Simpan",null).create();
  dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String t=title.getText().toString().trim(),b=body.getText().toString().trim();if(t.isEmpty()){title.setError("Judul wajib diisi");return;}ContentValues cv=new ContentValues();cv.put("title",t);cv.put("body",b);cv.put("category",cats[category.getSelectedItemPosition()]);cv.put("favorite",favorite.isChecked()?1:0);cv.put("updated",System.currentTimeMillis());if(id==null)db.getWritableDatabase().insert("notes",null,cv);else db.getWritableDatabase().update("notes",cv,"id=?",new String[]{""+id});dialog.dismiss();refresh();}));dialog.show();
 }
 static class DB extends SQLiteOpenHelper{DB(Context c){super(c,"rewinding_notes.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE notes(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT,category TEXT,favorite INTEGER DEFAULT 0,updated INTEGER)");}public void onUpgrade(SQLiteDatabase d,int o,int n){}}
}